// Guides for families reading reports written by child-development specialists.
// Each topic is localised rather than translated at build time. The shared
// structure keeps the series consistent while the clinical points stay specific.
const live = true
const L = {
  ashaTools: '<a href="https://www.asha.org/practice-portal/resources/assessment-tools-techniques-and-data-sources/" rel="noopener" target="_blank">ASHA, Assessment Tools, Techniques, and Data Sources</a>',
  ashaSchools: '<a href="https://www.asha.org/practice-portal/professional-issues/documentation-in-schools/" rel="noopener" target="_blank">ASHA, Documentation in Schools</a>',
  niceAutism: '<a href="https://www.nice.org.uk/guidance/cg128/chapter/Recommendations" rel="noopener" target="_blank">NICE, autism recognition, referral and diagnosis</a>',
  niceAdhd: '<a href="https://www.nice.org.uk/guidance/ng87/chapter/recommendations" rel="noopener" target="_blank">NICE, ADHD diagnosis and management</a>',
  whoIcf: '<a href="https://www.who.int/standards/classifications/international-classification-of-functioning-disability-and-health" rel="noopener" target="_blank">WHO, International Classification of Functioning, Disability and Health</a>',
  pearson: '<a href="https://www.pearsonassessments.com/content/dam/school/global/clinical/us/assets/featured-topics/assessment-primer-whitepaper.pdf" rel="noopener" target="_blank">Pearson, primer on standardised clinical assessment</a>',
}
const S = [L.ashaTools, L.whoIcf, L.niceAutism, L.niceAdhd]
const M = (pt, en, es) => ({ pt, en, es })

const T = [
  ['primeira-leitura-relatorio-clinico',
    M('Recebi o relatório da criança: por onde começar?', 'I received my child’s report: where do I start?', 'He recibido el informe: ¿por dónde empiezo?'),
    M('Uma primeira leitura em quatro passos para separar conclusão, perfil, recomendações e dúvidas.', 'A four-step first reading that separates conclusions, profile, recommendations and questions.', 'Una primera lectura en cuatro pasos para separar conclusión, perfil, recomendaciones y dudas.'),
    M('Comece pela pergunta que motivou a avaliação e pela conclusão, mas não pare no nome do diagnóstico. O corpo do relatório explica as observações, os métodos e o raciocínio que dão sentido à conclusão.', 'Start with the question that prompted assessment and the conclusion, but do not stop at the diagnostic label. The body explains the observations, methods and reasoning that give the conclusion meaning.', 'Empieza por la pregunta que motivó la evaluación y por la conclusión, pero no te detengas en la etiqueta diagnóstica. El cuerpo explica las observaciones, los métodos y el razonamiento que dan sentido a la conclusión.'),
    M('Sublinhe separadamente pontos fortes, necessidades, recomendações e frases que não compreende. Uma palavra técnica isolada não descreve a criança inteira nem determina o futuro.', 'Mark strengths, needs, recommendations and unclear phrases separately. One technical term does not describe the whole child or determine the future.', 'Marca por separado fortalezas, necesidades, recomendaciones y frases poco claras. Un término técnico aislado no describe al niño entero ni determina su futuro.'),
    M('Faça um resumo de uma página: o que foi avaliado, o que se concluiu, o que ajuda agora, quem fica responsável e quando rever. Leve as dúvidas à consulta de devolução.', 'Make a one-page summary: what was assessed, what was concluded, what helps now, who is responsible and when to review. Take questions to the feedback appointment.', 'Haz un resumen de una página: qué se evaluó, qué se concluyó, qué ayuda ahora, quién se responsabiliza y cuándo revisar. Lleva las dudas a la cita de devolución.')],
  ['linguagem-tecnica-relatorio-clinico',
    M('Como traduzir a linguagem técnica de um relatório clínico?', 'How can you translate technical language in a clinical report?', '¿Cómo traducir el lenguaje técnico de un informe clínico?'),
    M('Estratégias para compreender termos clínicos sem simplificar demais nem pesquisar cada palavra isoladamente.', 'Ways to understand clinical terms without oversimplifying or searching for each word in isolation.', 'Estrategias para comprender términos clínicos sin simplificar demasiado ni buscar cada palabra por separado.'),
    M('Termos como “compatível com”, “sugestivo de”, “significativo” ou “a monitorizar” têm um sentido dependente do contexto. “Significativo” pode ser estatístico, clínico ou funcional; peça que o profissional diga qual.', 'Terms such as “consistent with”, “suggestive of”, “significant” or “to monitor” depend on context. “Significant” may be statistical, clinical or functional; ask which meaning applies.', 'Términos como «compatible con», «sugestivo de», «significativo» o «a vigilar» dependen del contexto. «Significativo» puede ser estadístico, clínico o funcional; pregunta qué sentido tiene.'),
    M('Evite transformar uma expressão prudente numa certeza. “Não foi possível excluir” não confirma uma condição; “não observado” não prova que nunca acontece.', 'Do not turn cautious wording into certainty. “Could not be ruled out” does not confirm a condition; “not observed” does not mean it never happens.', 'No conviertas una formulación prudente en certeza. «No se pudo descartar» no confirma una condición; «no observado» no significa que nunca ocurra.'),
    M('Peça exemplos concretos: “Como se vê isto no dia a dia?”, “Que observação sustenta esta frase?” e “O que mudaria a interpretação?”. Registe a explicação ao lado do termo.', 'Ask for concrete examples: “What does this look like day to day?”, “What observation supports this sentence?” and “What would change the interpretation?”. Note the explanation beside the term.', 'Pide ejemplos concretos: «¿Cómo se ve esto en el día a día?», «¿Qué observación apoya esta frase?» y «¿Qué cambiaría la interpretación?». Anota la explicación junto al término.')],
  ['diagnostico-provisorio-diferencial-relatorio',
    M('Diagnóstico provisório e diagnóstico diferencial: o que significam?', 'Provisional and differential diagnosis: what do they mean?', 'Diagnóstico provisional y diferencial: ¿qué significan?'),
    M('Porque algumas conclusões ficam em aberto e como transformar a incerteza num plano de seguimento.', 'Why some conclusions remain open and how uncertainty can become a follow-up plan.', 'Por qué algunas conclusiones quedan abiertas y cómo convertir la incertidumbre en seguimiento.'),
    M('Um diagnóstico provisório indica que a hipótese é atualmente útil, mas ainda precisa de tempo ou informação. O diagnóstico diferencial reúne explicações que o profissional comparou; não é uma lista de diagnósticos confirmados.', 'A provisional diagnosis means the hypothesis is currently useful but still needs time or information. Differential diagnosis lists explanations the clinician considered; it is not a list of confirmed diagnoses.', 'Un diagnóstico provisional indica que la hipótesis es útil por ahora, pero necesita tiempo o información. El diagnóstico diferencial reúne explicaciones consideradas; no es una lista de diagnósticos confirmados.'),
    M('A incerteza pode ser clinicamente honesta, sobretudo quando a criança é pequena, os resultados divergem ou faltam dados de outros contextos. Não significa que a família tenha falhado nem que nada possa ser feito.', 'Uncertainty can be clinically honest, especially for young children, conflicting results or missing information from other settings. It does not mean the family has failed or that nothing can be done.', 'La incertidumbre puede ser clínicamente honesta, sobre todo en niños pequeños, resultados discordantes o falta de datos de otros contextos. No significa que la familia haya fallado ni que no pueda hacerse nada.'),
    M('Pergunte que informação falta, que apoios podem começar já, que sinais observar, quem acompanha e em que prazo rever a hipótese. Um plano claro torna a incerteza mais manejável.', 'Ask what information is missing, what support can start now, what to observe, who will follow up and when the hypothesis will be reviewed. A clear plan makes uncertainty more manageable.', 'Pregunta qué información falta, qué apoyos pueden empezar ya, qué observar, quién hará el seguimiento y cuándo revisar la hipótesis. Un plan claro hace más manejable la incertidumbre.')],
  ['pontuacao-padrao-relatorio-avaliacao',
    M('Pontuação padrão no relatório: como interpretar?', 'Standard scores in an assessment report: how do you read them?', 'Puntuación estándar en el informe: ¿cómo interpretarla?'),
    M('O que uma pontuação padronizada compara, quais são os seus limites e que perguntas fazer.', 'What a standard score compares, its limits and the questions worth asking.', 'Qué compara una puntuación estandarizada, sus límites y qué conviene preguntar.'),
    M('A pontuação bruta costuma ser convertida para uma escala definida pelo manual do teste. A pontuação padrão compara o desempenho com a amostra normativa adequada à idade ou escolaridade; a média e a dispersão variam entre instrumentos.', 'A raw score is usually converted to a scale defined by the test manual. A standard score compares performance with the relevant age or grade norm sample; the mean and spread vary across instruments.', 'La puntuación directa suele convertirse a una escala definida por el manual. La puntuación estándar compara el rendimiento con la muestra normativa de edad o curso; la media y la dispersión varían entre instrumentos.'),
    M('Não leia o número sem o nome do teste, a área medida, a amostra de comparação e as condições de aplicação. Língua, cultura, atenção, fadiga, motricidade e adaptações podem afetar a validade da comparação.', 'Never read the number without the test name, construct measured, comparison sample and testing conditions. Language, culture, attention, fatigue, motor demands and adaptations may affect validity.', 'No leas el número sin conocer la prueba, el área medida, la muestra de comparación y las condiciones. Lengua, cultura, atención, cansancio, motricidad y adaptaciones pueden afectar la validez.'),
    M('Pergunte qual é o intervalo provável da pontuação, se a norma representa a criança e como o resultado combina com observação e vida diária. O perfil entre tarefas costuma ser mais útil do que um total isolado.', 'Ask about the likely score range, whether the norms represent the child and how the result fits observation and daily life. The pattern across tasks is often more useful than one total.', 'Pregunta por el intervalo probable, si las normas representan al niño y cómo encaja el resultado con la observación y la vida diaria. El perfil entre tareas suele ser más útil que un total aislado.')],
  ['percentil-relatorio-avaliacao',
    M('Percentil no relatório: o que quer dizer?', 'What does a percentile in a report mean?', 'Percentil en el informe: ¿qué significa?'),
    M('Porque percentil não é percentagem de respostas certas e como evitar comparações assustadoras.', 'Why a percentile is not a percentage correct and how to avoid frightening comparisons.', 'Por qué un percentil no es un porcentaje de aciertos y cómo evitar comparaciones alarmantes.'),
    M('O percentil indica a posição relativa na amostra normativa. Percentil 30 significa que o resultado foi igual ou superior ao de cerca de 30% dessa amostra, não que a criança acertou 30% nem que “tem 30% de capacidade”.', 'A percentile shows relative position in the norm sample. The 30th percentile means the result equalled or exceeded about 30% of that sample; it does not mean 30% correct or “30% ability”.', 'El percentil indica la posición relativa en la muestra normativa. Percentil 30 significa que el resultado igualó o superó aproximadamente al 30% de esa muestra; no significa 30% de aciertos ni «30% de capacidad».'),
    M('Percentis não têm intervalos iguais: a diferença entre dois percentis não representa sempre a mesma diferença de desempenho. Pequenas variações na pontuação podem mudar bastante o percentil em certas zonas da distribuição.', 'Percentiles are not equal intervals: the gap between two percentiles does not always represent the same performance difference. Small score changes may shift percentiles markedly in parts of the distribution.', 'Los percentiles no tienen intervalos iguales: la distancia entre dos percentiles no representa siempre la misma diferencia. Pequeños cambios de puntuación pueden mover mucho el percentil en algunas zonas.'),
    M('Use o percentil para compreender uma comparação específica, nunca para classificar o valor ou potencial da criança. Peça também exemplos funcionais, intervalo de confiança e limitações do teste.', 'Use a percentile to understand a specific comparison, never to rank a child’s worth or potential. Ask for functional examples, confidence intervals and test limitations too.', 'Usa el percentil para comprender una comparación concreta, nunca para clasificar el valor o potencial del niño. Pide también ejemplos funcionales, intervalo de confianza y limitaciones de la prueba.')],
  ['intervalo-confianca-relatorio-avaliacao',
    M('Intervalo de confiança: porque o resultado não é um número exato?', 'Confidence intervals: why is a result not an exact number?', 'Intervalo de confianza: ¿por qué el resultado no es un número exacto?'),
    M('Como a margem de incerteza ajuda a ler testes com mais rigor e menos ansiedade.', 'How a margin of uncertainty supports more accurate, less anxious interpretation.', 'Cómo el margen de incertidumbre ayuda a leer pruebas con más rigor y menos ansiedad.'),
    M('Qualquer medição tem erro. O intervalo de confiança apresenta uma faixa plausível para a pontuação, segundo o modelo do teste e o nível de confiança usado. Recorda que o número observado não é uma medida perfeita e imutável.', 'Every measurement contains error. A confidence interval gives a plausible score range under the test model and chosen confidence level. It reminds us that the observed number is not perfect or immutable.', 'Toda medición contiene error. El intervalo de confianza ofrece un rango plausible según el modelo de la prueba y el nivel elegido. Recuerda que el número observado no es una medida perfecta ni inmutable.'),
    M('Dois resultados próximos podem ter intervalos sobrepostos; por isso, uma diferença visual entre números pode não sustentar uma conclusão firme. A interpretação depende do manual e da pergunta clínica.', 'Two nearby results may have overlapping intervals, so a visible numerical gap may not support a firm conclusion. Interpretation depends on the manual and clinical question.', 'Dos resultados cercanos pueden tener intervalos superpuestos; una diferencia visible entre números puede no sostener una conclusión firme. La interpretación depende del manual y de la pregunta clínica.'),
    M('Pergunte se as diferenças entre áreas são estatisticamente e clinicamente relevantes, e confirme se houve fatores que tornaram a estimativa menos estável. Foque decisões em várias fontes, não em um ponto de corte sozinho.', 'Ask whether differences across areas are statistically and clinically meaningful, and whether anything made the estimate less stable. Base decisions on several sources, not one cut-off.', 'Pregunta si las diferencias entre áreas son estadística y clínicamente relevantes y si algo hizo menos estable la estimación. Basa las decisiones en varias fuentes, no en un único punto de corte.')],
  ['idade-equivalente-relatorio-avaliacao',
    M('“Idade equivalente” no relatório: como deve ser lida?', '“Age equivalent” in a report: how should it be read?', '«Edad equivalente» en el informe: ¿cómo debe leerse?'),
    M('Porque uma idade equivalente não transforma a criança numa criança mais nova nem prevê o futuro.', 'Why an age equivalent does not turn a child into a younger child or predict the future.', 'Por qué una edad equivalente no convierte al niño en otro más pequeño ni predice el futuro.'),
    M('Uma idade equivalente indica que a pontuação bruta se aproxima da pontuação típica de uma idade na amostra daquele teste. Não significa que todo o desenvolvimento esteja nessa idade.', 'An age equivalent means the raw score resembles the typical score for an age in that test sample. It does not mean the child’s whole development is at that age.', 'Una edad equivalente indica que la puntuación directa se parece a la típica de una edad en la muestra de esa prueba. No significa que todo el desarrollo esté en esa edad.'),
    M('A criança pode ter um perfil muito diferente entre linguagem, autonomia, motricidade, aprendizagem e relações. Idades equivalentes também podem ser imprecisas e dar uma falsa sensação de simplicidade.', 'A child may have very different profiles across language, independence, movement, learning and relationships. Age equivalents can also be imprecise and falsely simple.', 'El niño puede tener perfiles muy distintos en lenguaje, autonomía, motricidad, aprendizaje y relaciones. Las edades equivalentes también pueden ser imprecisas y dar una falsa sensación de simplicidad.'),
    M('Pergunte que tarefas concretas a criança conseguiu fazer e quais são os próximos objetivos funcionais. Para planear apoio, descrições de competências são geralmente mais úteis do que dizer que a criança “funciona como” outra idade.', 'Ask which tasks the child completed and what the next functional goals are. Skill descriptions are usually more useful for planning than saying a child “functions like” another age.', 'Pregunta qué tareas concretas realizó y cuáles son los siguientes objetivos funcionales. Para planificar apoyos, describir habilidades suele ser más útil que decir que «funciona como» otra edad.')],
  ['pontos-fortes-necessidades-relatorio',
    M('Pontos fortes e necessidades: como encontrar o perfil no relatório?', 'Strengths and needs: how do you find the profile in a report?', 'Fortalezas y necesidades: ¿cómo encontrar el perfil en el informe?'),
    M('Ler além do défice para perceber recursos, barreiras, participação e apoios úteis.', 'Reading beyond deficits to identify resources, barriers, participation and useful support.', 'Leer más allá del déficit para identificar recursos, barreras, participación y apoyos útiles.'),
    M('Um relatório útil descreve o que a criança consegue fazer, em que condições participa melhor e onde encontra barreiras. Pontos fortes não são um adorno: ajudam a escolher estratégias e a criar oportunidades de sucesso.', 'A useful report describes what the child can do, the conditions that support participation and the barriers encountered. Strengths are not decoration: they guide strategies and opportunities for success.', 'Un informe útil describe lo que el niño puede hacer, en qué condiciones participa mejor y qué barreras encuentra. Las fortalezas no son un adorno: orientan estrategias y oportunidades de éxito.'),
    M('A mesma capacidade pode aparecer de forma diferente conforme o ambiente, a familiaridade, o apoio visual, o tempo de resposta ou a exigência sensorial. Isto não torna o perfil contraditório; mostra condições relevantes.', 'The same ability may look different with environment, familiarity, visual support, response time or sensory demand. This does not make the profile contradictory; it identifies relevant conditions.', 'La misma habilidad puede verse distinta según el entorno, la familiaridad, el apoyo visual, el tiempo o la demanda sensorial. No vuelve contradictorio el perfil; muestra condiciones relevantes.'),
    M('Crie duas colunas: “recursos a aproveitar” e “barreiras a reduzir”. Ligue cada recomendação a uma delas e pergunte como medir participação, autonomia ou comunicação no quotidiano.', 'Create two columns: “resources to build on” and “barriers to reduce”. Link each recommendation to one and ask how daily participation, independence or communication will be monitored.', 'Crea dos columnas: «recursos que aprovechar» y «barreras que reducir». Relaciona cada recomendación con una y pregunta cómo observar participación, autonomía o comunicación cotidiana.')],
  ['recomendacoes-relatorio-por-onde-comecar',
    M('Muitas recomendações no relatório: por onde começar?', 'A report has many recommendations: where should you start?', 'Muchas recomendaciones en el informe: ¿por dónde empezar?'),
    M('Como priorizar uma lista longa segundo segurança, participação, impacto e viabilidade familiar.', 'How to prioritise a long list by safety, participation, impact and family feasibility.', 'Cómo priorizar una lista larga según seguridad, participación, impacto y viabilidad familiar.'),
    M('Uma lista extensa não significa que tudo deva começar ao mesmo tempo. Algumas recomendações são urgentes; outras são opções, objetivos futuros ou sugestões que dependem de nova avaliação.', 'A long list does not mean everything must begin at once. Some recommendations are urgent; others are options, future goals or suggestions that depend on further assessment.', 'Una lista extensa no significa que todo deba empezar a la vez. Algunas recomendaciones son urgentes; otras son opciones, metas futuras o sugerencias que dependen de otra evaluación.'),
    M('Priorize primeiro segurança e saúde, depois comunicação de necessidades, participação nas rotinas e barreiras que causam maior sofrimento. Considere também tempo, custo, deslocações e capacidade real da família.', 'Prioritise safety and health first, then communication of needs, participation in routines and barriers causing the greatest distress. Also consider time, cost, travel and the family’s real capacity.', 'Prioriza primero seguridad y salud, después comunicación de necesidades, participación en rutinas y barreras que causan mayor malestar. Considera también tiempo, coste, desplazamientos y capacidad real familiar.'),
    M('Escolha um a três passos para o próximo mês, defina quem contacta quem e marque uma revisão. Peça ao profissional para distinguir “essencial agora”, “útil quando possível” e “a reconsiderar depois”.', 'Choose one to three steps for the next month, decide who contacts whom and set a review. Ask the clinician to separate “essential now”, “useful when possible” and “reconsider later”.', 'Elige de uno a tres pasos para el próximo mes, decide quién contacta con quién y fija una revisión. Pide separar «esencial ahora», «útil cuando sea posible» y «reconsiderar después».')],
  ['objetivos-relatorio-plano-apoio',
    M('Como transformar o relatório em objetivos úteis?', 'How can a report become useful goals?', '¿Cómo convertir el informe en objetivos útiles?'),
    M('Passar de recomendações gerais para objetivos observáveis, significativos e revistos em conjunto.', 'Turning broad recommendations into observable, meaningful goals reviewed together.', 'Pasar de recomendaciones generales a objetivos observables, significativos y revisados en conjunto.'),
    M('“Estimular linguagem” ou “melhorar atenção” são direções, não objetivos completos. Um objetivo útil diz em que rotina, com que apoio e para que participação se pretende uma mudança.', '“Encourage language” or “improve attention” are directions, not complete goals. A useful goal states the routine, support and participation outcome intended.', '«Estimular el lenguaje» o «mejorar la atención» son direcciones, no objetivos completos. Un objetivo útil indica la rutina, el apoyo y la participación buscada.'),
    M('O objetivo deve ser relevante para a criança e família, observável sem a transformar numa sequência de testes e flexível perante o desenvolvimento. Nem todo o progresso cabe numa percentagem.', 'A goal should matter to the child and family, be observable without turning life into constant testing, and remain flexible as development changes. Not all progress fits a percentage.', 'El objetivo debe importar al niño y a la familia, ser observable sin convertir la vida en pruebas constantes y ser flexible ante el desarrollo. No todo progreso cabe en un porcentaje.'),
    M('Converta uma recomendação numa frase: “Durante [rotina], a criança poderá [participação], com [apoio], observado por [exemplos]”. Combine quando rever e o que fazer se a estratégia não ajudar.', 'Turn a recommendation into: “During [routine], the child will be able to [participate], with [support], observed through [examples].” Agree when to review and what to do if it does not help.', 'Convierte una recomendación en: «Durante [rutina], el niño podrá [participar], con [apoyo], observado mediante [ejemplos]». Acordad cuándo revisar y qué hacer si no ayuda.')],
  ['relatorio-terapia-fala-compreender',
    M('Como compreender um relatório de terapia da fala?', 'How do you understand a speech and language therapy report?', '¿Cómo comprender un informe de logopedia o fonoaudiología?'),
    M('Compreensão, expressão, sons, comunicação funcional e contexto: o que procurar no documento.', 'Understanding, expression, speech sounds, functional communication and context: what to look for.', 'Comprensión, expresión, sonidos, comunicación funcional y contexto: qué buscar.'),
    M('O relatório pode separar linguagem recetiva e expressiva, fala, voz, fluência, motricidade orofacial, alimentação ou comunicação aumentativa. Nem todas estas áreas são avaliadas em todas as consultas.', 'The report may separate receptive and expressive language, speech, voice, fluency, oral motor function, feeding or AAC. Not every area is assessed at every appointment.', 'El informe puede separar lenguaje receptivo y expresivo, habla, voz, fluidez, motricidad orofacial, alimentación o CAA. No todas las áreas se evalúan en cada consulta.'),
    M('Resultados padronizados precisam de ser adequados à língua e ao perfil. Amostras de conversa, brincadeira, narrativas e relatos familiares podem mostrar competências que um teste estruturado não capta sozinho.', 'Standardised results must suit the child’s language and profile. Conversation, play and narrative samples and family reports may show skills a structured test cannot capture alone.', 'Los resultados estandarizados deben adecuarse a la lengua y al perfil. Muestras de conversación, juego y narración y relatos familiares pueden mostrar habilidades que una prueba no capta sola.'),
    M('Pergunte que área interfere mais com o quotidiano, que estratégias os adultos devem modelar, como aceitar gesto ou CAA e que sinais indicarão progresso funcional. A intervenção deve ligar-se à participação, não apenas a itens de teste.', 'Ask which area most affects daily life, what adults should model, how gesture or AAC will be accepted and what will show functional progress. Support should link to participation, not only test items.', 'Pregunta qué área afecta más a la vida diaria, qué deben modelar los adultos, cómo aceptar gesto o CAA y qué mostrará progreso funcional. El apoyo debe vincularse a participación, no solo a ítems de prueba.')],
  ['relatorio-psicologia-infantil-compreender',
    M('Como ler um relatório de psicologia infantil?', 'How do you read a child psychology report?', '¿Cómo leer un informe de psicología infantil?'),
    M('Integrar entrevista, observação, questionários e testes sem reduzir emoções ou comportamento a uma escala.', 'Integrating interviews, observation, questionnaires and tests without reducing emotions or behaviour to a scale.', 'Integrar entrevista, observación, cuestionarios y pruebas sin reducir emociones o conducta a una escala.'),
    M('O relatório psicológico pode abordar emoções, comportamento, relações, aprendizagem, cognição e contexto familiar ou escolar, conforme a pergunta inicial. Confirme o objetivo antes de interpretar cada resultado.', 'A psychology report may address emotions, behaviour, relationships, learning, cognition and family or school context, depending on the referral question. Confirm the purpose before reading each result.', 'El informe psicológico puede abordar emociones, conducta, relaciones, aprendizaje, cognición y contexto familiar o escolar, según la pregunta inicial. Confirma el objetivo antes de leer cada resultado.'),
    M('Questionários descrevem perceções de informantes e podem divergir entre casa e escola. A divergência não torna uma resposta falsa: pode revelar exigências, apoios ou relações diferentes em cada contexto.', 'Questionnaires describe informants’ perspectives and may differ between home and school. A difference does not make one response false; it may reveal different demands, support or relationships.', 'Los cuestionarios describen perspectivas y pueden diferir entre casa y escuela. La divergencia no vuelve falsa una respuesta; puede mostrar demandas, apoyos o relaciones distintas.'),
    M('Procure a formulação que liga fatores, impacto e proteção, não apenas rótulos. Pergunte que mudanças ambientais, competências e apoios são recomendados e como a voz da criança foi considerada.', 'Look for a formulation linking contributing factors, impact and protection, not labels alone. Ask what environmental changes, skills and support are recommended and how the child’s voice was included.', 'Busca una formulación que conecte factores, impacto y protección, no solo etiquetas. Pregunta qué cambios ambientales, habilidades y apoyos se recomiendan y cómo se consideró la voz del niño.')],
  ['relatorio-neuropsicologico-infantil',
    M('Relatório neuropsicológico infantil: como ler o perfil?', 'Child neuropsychological report: how do you read the profile?', 'Informe neuropsicológico infantil: ¿cómo leer el perfil?'),
    M('Atenção, memória, linguagem e funções executivas formam um perfil, não uma nota única.', 'Attention, memory, language and executive functions form a profile, not one single mark.', 'Atención, memoria, lenguaje y funciones ejecutivas forman un perfil, no una nota única.'),
    M('A avaliação neuropsicológica examina padrões entre tarefas e relaciona-os com história, aprendizagem e funcionamento. Uma pontuação baixa numa tarefa pode ter várias explicações e não identifica sozinha a causa.', 'Neuropsychological assessment examines patterns across tasks and relates them to history, learning and functioning. A low score on one task may have several explanations and does not identify the cause alone.', 'La evaluación neuropsicológica examina patrones entre tareas y los relaciona con historia, aprendizaje y funcionamiento. Una puntuación baja puede tener varias explicaciones y no identifica sola la causa.'),
    M('Atenção, linguagem, velocidade, motricidade, ansiedade, sono e familiaridade com a tarefa podem influenciar várias medidas. Leia as observações comportamentais e a validade antes do gráfico de resultados.', 'Attention, language, speed, motor demands, anxiety, sleep and task familiarity may influence many measures. Read behavioural observations and validity before the score chart.', 'Atención, lenguaje, velocidad, motricidad, ansiedad, sueño y familiaridad pueden influir en muchas medidas. Lee las observaciones y la validez antes del gráfico de resultados.'),
    M('Peça exemplos de como o padrão aparece na aprendizagem e nas rotinas, que estratégias compensam dificuldades e que capacidades podem apoiar outras. Compare reavaliações apenas quando instrumentos e condições o permitirem.', 'Ask how the pattern appears in learning and routines, which strategies compensate for difficulties and which strengths can support other areas. Compare reassessments only when tools and conditions allow.', 'Pregunta cómo aparece el patrón en el aprendizaje y las rutinas, qué estrategias compensan dificultades y qué fortalezas apoyan otras áreas. Compara reevaluaciones solo si pruebas y condiciones lo permiten.')],
  ['relatorio-terapia-ocupacional-sensorial',
    M('Relatório de terapia ocupacional e perfil sensorial: como interpretar?', 'Occupational therapy and sensory profile report: how do you interpret it?', 'Informe de terapia ocupacional y perfil sensorial: ¿cómo interpretarlo?'),
    M('Ligar processamento sensorial, atividades diárias e ambiente sem tratar preferências como diagnóstico.', 'Linking sensory processing, daily activities and environment without treating preferences as a diagnosis.', 'Relacionar procesamiento sensorial, actividades diarias y entorno sin convertir preferencias en diagnóstico.'),
    M('Um relatório de terapia ocupacional centra-se na participação em atividades como vestir, comer, brincar, escrever ou organizar rotinas. Questionários sensoriais descrevem padrões observados, não produzem por si um diagnóstico médico.', 'An occupational therapy report focuses on participation in activities such as dressing, eating, play, writing or routines. Sensory questionnaires describe observed patterns; they do not produce a medical diagnosis by themselves.', 'Un informe de terapia ocupacional se centra en participar en actividades como vestirse, comer, jugar, escribir u organizar rutinas. Los cuestionarios sensoriales describen patrones; no diagnostican por sí solos.'),
    M('Uma reação pode depender do ruído, previsibilidade, dor, comunicação, ansiedade ou exigência da tarefa. A interpretação deve ligar o padrão ao contexto e excluir explicações relevantes quando necessário.', 'A response may depend on noise, predictability, pain, communication, anxiety or task demands. Interpretation should connect the pattern to context and consider relevant alternative explanations.', 'Una reacción puede depender del ruido, la previsibilidad, el dolor, la comunicación, la ansiedad o la tarea. La interpretación debe conectar el patrón con el contexto y considerar otras explicaciones.'),
    M('Pergunte que barreira concreta se pretende reduzir, que adaptação é segura e realizável e como se saberá se melhora participação. Evite programas intensivos sem objetivo funcional ou promessas desproporcionadas.', 'Ask which concrete barrier is being reduced, which adaptation is safe and feasible and how improved participation will be recognised. Avoid intensive programmes without a functional goal or disproportionate promises.', 'Pregunta qué barrera concreta se busca reducir, qué adaptación es segura y viable y cómo se sabrá si mejora la participación. Evita programas intensivos sin objetivo funcional o promesas desproporcionadas.')],
  ['relatorio-audiologia-infantil',
    M('Relatório de audiologia infantil: o que significam os resultados?', 'Child audiology report: what do the results mean?', 'Informe de audiología infantil: ¿qué significan los resultados?'),
    M('Tipo de teste, ouvido avaliado, fiabilidade e próximos passos para compreender a audição da criança.', 'Test type, ear, reliability and next steps for understanding a child’s hearing.', 'Tipo de prueba, oído, fiabilidad y siguientes pasos para comprender la audición.'),
    M('A audiologia infantil pode usar métodos diferentes conforme a idade e cooperação: medidas fisiológicas, observação comportamental ou respostas condicionadas. Cada método responde a uma pergunta diferente.', 'Paediatric audiology may use different methods according to age and participation: physiological measures, behavioural observation or conditioned responses. Each method answers a different question.', 'La audiología infantil puede usar métodos distintos según edad y participación: medidas fisiológicas, observación conductual o respuestas condicionadas. Cada método responde a una pregunta diferente.'),
    M('“Passou” num rastreio não descreve toda a audição; “inconclusivo” não confirma perda auditiva. Cera, líquido no ouvido médio, ruído, estado da criança e qualidade da resposta podem exigir repetição.', '“Pass” on screening does not describe all hearing; “inconclusive” does not confirm hearing loss. Wax, middle-ear fluid, noise, the child’s state and response quality may require repeat testing.', '«Apto» en un cribado no describe toda la audición; «no concluyente» no confirma pérdida auditiva. Cerumen, líquido, ruido, estado del niño y calidad de respuesta pueden exigir repetir.'),
    M('Pergunte que ouvido e frequências foram avaliados, quão fiável foi a sessão, se é preciso repetir ou encaminhar e que sinais justificam contacto antecipado. Não adie apoio à comunicação enquanto se esclarece a audição.', 'Ask which ear and frequencies were assessed, how reliable the session was, whether repeat testing or referral is needed and what signs warrant earlier contact. Do not delay communication support while hearing is clarified.', 'Pregunta qué oído y frecuencias se evaluaron, cuán fiable fue la sesión, si hay que repetir o derivar y qué señales justifican adelantar el contacto. No retrases apoyos comunicativos mientras se aclara la audición.')],
  ['relatorio-escolar-e-clinico-diferencas',
    M('Relatório escolar e relatório clínico: porque podem ser diferentes?', 'School and clinical reports: why can they differ?', 'Informe escolar e informe clínico: ¿por qué pueden ser distintos?'),
    M('Objetivos, contextos e métodos diferentes podem produzir descrições distintas e igualmente úteis.', 'Different purposes, settings and methods may produce different, equally useful descriptions.', 'Objetivos, contextos y métodos distintos pueden producir descripciones diferentes e igualmente útiles.'),
    M('O relatório escolar descreve aprendizagem e participação no ambiente educativo; o clínico responde a uma pergunta de saúde ou desenvolvimento. Usam linguagem, instrumentos e critérios diferentes.', 'A school report describes learning and participation in education; a clinical report answers a health or developmental question. They use different language, tools and criteria.', 'El informe escolar describe aprendizaje y participación educativa; el clínico responde a una pregunta de salud o desarrollo. Usan lenguaje, instrumentos y criterios distintos.'),
    M('A criança pode mostrar competências diferentes numa consulta individual e numa sala com ruído, pares, transições e exigências prolongadas. A diferença entre documentos é informação a integrar, não uma competição por quem tem razão.', 'A child may show different skills in a one-to-one clinic and a classroom with noise, peers, transitions and sustained demands. The difference is information to integrate, not a contest over who is right.', 'El niño puede mostrar habilidades distintas en una consulta individual y en un aula con ruido, compañeros, transiciones y demandas prolongadas. La diferencia se integra; no es una competición por tener razón.'),
    M('Compare a pergunta, data, contexto e apoios disponíveis em cada avaliação. Com consentimento adequado, peça que profissionais traduzam as conclusões em estratégias coerentes; confirme localmente procedimentos escolares e partilha de dados.', 'Compare the question, date, setting and support available in each assessment. With appropriate consent, ask professionals to turn findings into coherent strategies; check local school and data-sharing procedures.', 'Compara la pregunta, fecha, contexto y apoyos de cada evaluación. Con el consentimiento adecuado, pide estrategias coherentes; confirma localmente los procedimientos escolares y de intercambio de datos.')],
  ['niveis-suporte-autismo-relatorio',
    M('Níveis de suporte no autismo: o que dizem e o que não dizem?', 'Autism support levels: what do they say and not say?', 'Niveles de apoyo en autismo: ¿qué dicen y qué no?'),
    M('Compreender descritores de apoio sem os transformar numa identidade fixa ou previsão de futuro.', 'Understanding support descriptors without turning them into a fixed identity or forecast.', 'Comprender descriptores de apoyo sin convertirlos en identidad fija ni pronóstico.'),
    M('Quando o sistema diagnóstico usado inclui níveis de suporte, estes procuram descrever necessidades atuais em áreas específicas. Não são uma medida global do valor, inteligência ou potencial da criança.', 'When the diagnostic system used includes support levels, they aim to describe current needs in specific areas. They are not a global measure of worth, intelligence or potential.', 'Cuando el sistema diagnóstico incluye niveles de apoyo, buscan describir necesidades actuales en áreas concretas. No miden globalmente el valor, la inteligencia ni el potencial del niño.'),
    M('As necessidades podem variar entre comunicação social e padrões repetitivos, e mudar com ambiente, saúde, exigências, aprendizagem e apoios. Um único nível pode esconder um perfil desigual.', 'Needs may differ across social communication and repetitive patterns, and change with environment, health, demands, learning and support. One level may hide an uneven profile.', 'Las necesidades pueden variar entre comunicación social y patrones repetitivos, y cambiar con entorno, salud, demandas, aprendizaje y apoyos. Un único nivel puede ocultar un perfil desigual.'),
    M('Peça exemplos funcionais e apoios concretos para cada área. Reveja o plano quando as rotinas ou necessidades mudarem; não retire apoio apenas porque uma competência apareceu numa situação estruturada.', 'Ask for functional examples and concrete support in each area. Review the plan when routines or needs change; do not remove support solely because a skill appeared in one structured situation.', 'Pide ejemplos funcionales y apoyos concretos para cada área. Revisa el plan cuando cambien rutinas o necesidades; no retires apoyo solo porque una habilidad apareció en una situación estructurada.')],
  ['apresentacao-gravidade-tdah-relatorio',
    M('TDAH no relatório: apresentação e gravidade explicadas', 'ADHD in a report: presentation and severity explained', 'TDAH en el informe: presentación y gravedad explicadas'),
    M('Porque sintomas, impacto em vários contextos e condições coexistentes importam mais do que uma escala isolada.', 'Why symptoms, impact across settings and coexisting conditions matter more than one rating scale.', 'Por qué síntomas, impacto en varios contextos y condiciones coexistentes importan más que una escala aislada.'),
    M('O relatório pode descrever uma apresentação com predomínio de desatenção, hiperatividade/impulsividade ou combinação. A designação organiza o padrão atual e pode mudar ao longo do desenvolvimento.', 'A report may describe predominantly inattentive, hyperactive/impulsive or combined presentation. The term organises the current pattern and may change through development.', 'El informe puede describir presentación predominantemente inatenta, hiperactiva/impulsiva o combinada. La denominación organiza el patrón actual y puede cambiar con el desarrollo.'),
    M('A gravidade considera sintomas e, sobretudo, impacto. Questionários ajudam, mas o diagnóstico não deve basear-se apenas numa escala; requer história, diferentes contextos e alternativas clínicas.', 'Severity considers symptoms and, importantly, impact. Rating scales help, but diagnosis should not rest on a scale alone; it needs history, different settings and alternative explanations.', 'La gravedad considera síntomas y, sobre todo, impacto. Las escalas ayudan, pero el diagnóstico no debe basarse solo en ellas; necesita historia, distintos contextos y otras explicaciones.'),
    M('Pergunte onde surgem as maiores barreiras, que modificações ambientais ajudam e como acompanhar sono, emoções, aprendizagem e relações. O plano deve apoiar objetivos da criança, não apenas reduzir uma pontuação.', 'Ask where barriers are greatest, which environmental changes help and how sleep, emotions, learning and relationships will be followed. The plan should support the child’s goals, not merely lower a score.', 'Pregunta dónde están las mayores barreras, qué cambios ambientales ayudan y cómo seguir sueño, emociones, aprendizaje y relaciones. El plan debe apoyar metas del niño, no solo bajar una puntuación.')],
  ['pdl-relatorio-diagnostico-linguagem',
    M('PDL no relatório: o que significa para a criança?', 'DLD in a report: what does it mean for a child?', 'TDL en el informe: ¿qué significa para el niño?'),
    M('Ler um diagnóstico de perturbação ou trastorno do desenvolvimento da linguagem com foco no perfil e apoio.', 'Reading a developmental language disorder diagnosis with a focus on profile and support.', 'Leer un diagnóstico de trastorno del desarrollo del lenguaje con foco en perfil y apoyo.'),
    M('A PDL/TDL descreve dificuldades persistentes de linguagem com impacto funcional. O perfil pode envolver compreensão, expressão, gramática, vocabulário, discurso ou aprendizagem verbal em combinações diferentes.', 'DLD describes persistent language difficulties with functional impact. The profile may involve understanding, expression, grammar, vocabulary, discourse or verbal learning in different combinations.', 'El TDL describe dificultades persistentes del lenguaje con impacto funcional. El perfil puede implicar comprensión, expresión, gramática, vocabulario, discurso o aprendizaje verbal en combinaciones distintas.'),
    M('O diagnóstico não significa ausência de progresso nem define inteligência. Crianças multilingues devem ser avaliadas considerando todas as línguas e oportunidades de exposição; diferença linguística não é perturbação.', 'The diagnosis does not mean no progress or define intelligence. Multilingual children should be assessed across their languages and exposure opportunities; language difference is not disorder.', 'El diagnóstico no significa ausencia de progreso ni define la inteligencia. Los niños multilingües deben evaluarse considerando sus lenguas y exposición; diferencia lingüística no es trastorno.'),
    M('Peça um mapa claro do que ajuda a compreender e expressar-se em casa e na escola: tempo de resposta, linguagem simples, apoios visuais, repetição significativa ou CAA quando indicada. Defina objetivos funcionais e revisão.', 'Ask for a clear map of what supports understanding and expression at home and school: response time, clear language, visual support, meaningful repetition or AAC when indicated. Set functional goals and review.', 'Pide un mapa claro de lo que ayuda a comprender y expresarse en casa y escuela: tiempo, lenguaje claro, apoyos visuales, repetición significativa o CAA cuando proceda. Define objetivos funcionales y revisión.')],
  ['deficiencia-intelectual-funcionamento-adaptativo-relatorio',
    M('Deficiência intelectual no relatório: porque conta a adaptação?', 'Intellectual disability in a report: why does adaptive functioning matter?', 'Discapacidad intelectual en el informe: ¿por qué importa la adaptación?'),
    M('Compreender cognição e funcionamento adaptativo sem reduzir a pessoa ao QI.', 'Understanding cognition and adaptive functioning without reducing a person to IQ.', 'Comprender cognición y funcionamiento adaptativo sin reducir a la persona al CI.'),
    M('A avaliação considera funcionamento intelectual e competências adaptativas conceptuais, sociais e práticas. Uma pontuação cognitiva isolada não descreve como a criança comunica, participa, resolve rotinas ou usa apoio.', 'Assessment considers intellectual functioning and conceptual, social and practical adaptive skills. One cognitive score does not describe how a child communicates, participates, manages routines or uses support.', 'La evaluación considera funcionamiento intelectual y habilidades adaptativas conceptuales, sociales y prácticas. Una puntuación cognitiva aislada no describe cómo comunica, participa, resuelve rutinas o usa apoyos.'),
    M('O desempenho depende de oportunidades, comunicação, acessibilidade, cultura e expectativas. Relatos de adultos devem referir comportamentos reais em contextos conhecidos, não aquilo que imaginam que a criança faria.', 'Performance depends on opportunities, communication, accessibility, culture and expectations. Adult reports should describe real behaviour in familiar settings, not imagined performance.', 'El rendimiento depende de oportunidades, comunicación, accesibilidad, cultura y expectativas. Los relatos adultos deben describir conductas reales en contextos conocidos, no lo que imaginan que haría.'),
    M('Procure recomendações que aumentem autonomia com apoio, escolha, comunicação e participação. Divida tarefas, ensine em contextos reais e reveja apoios sem confundir independência com fazer tudo sem ajuda.', 'Look for recommendations that increase supported autonomy, choice, communication and participation. Break tasks down, teach in real settings and review support without equating independence with no help.', 'Busca recomendaciones que aumenten autonomía con apoyo, elección, comunicación y participación. Divide tareas, enseña en contextos reales y revisa apoyos sin equiparar independencia a hacerlo todo sin ayuda.')],
  ['dislexia-relatorio-avaliacao',
    M('Dislexia no relatório: como compreender os resultados?', 'Dyslexia in a report: how do you understand the results?', 'Dislexia en el informe: ¿cómo comprender los resultados?'),
    M('Precisão, fluência, descodificação e ortografia: ligar o perfil de leitura ao ensino e às adaptações.', 'Accuracy, fluency, decoding and spelling: linking the reading profile to teaching and adjustments.', 'Precisión, fluidez, decodificación y ortografía: relacionar el perfil lector con enseñanza y ajustes.'),
    M('A avaliação pode examinar leitura de palavras e pseudopalavras, fluência, compreensão, ortografia, consciência fonológica, memória verbal e história de ensino. Nenhuma tarefa isolada resume a leitura.', 'Assessment may examine word and nonword reading, fluency, comprehension, spelling, phonological awareness, verbal memory and teaching history. No single task summarises reading.', 'La evaluación puede examinar lectura de palabras y pseudopalabras, fluidez, comprensión, ortografía, conciencia fonológica, memoria verbal e historia educativa. Ninguna tarea resume la lectura.'),
    M('Dificuldade específica de leitura não equivale a falta de esforço ou pouca inteligência. Língua de escolarização, qualidade do ensino, visão, audição, atenção e oportunidades precisam de contexto.', 'A specific reading difficulty does not mean low effort or intelligence. Language of instruction, teaching quality, vision, hearing, attention and opportunities need context.', 'Una dificultad específica de lectura no equivale a poco esfuerzo ni baja inteligencia. Lengua de enseñanza, calidad educativa, visión, audición, atención y oportunidades necesitan contexto.'),
    M('Peça prioridades de ensino explícito e sistemático, formas de acesso ao currículo e indicadores de progresso. Confirme os procedimentos escolares na jurisdição local; um diagnóstico clínico não determina sozinho medidas educativas universais.', 'Ask for priorities for explicit, systematic teaching, curriculum access and progress indicators. Check school procedures locally; a clinical diagnosis does not by itself determine universal educational measures.', 'Pide prioridades de enseñanza explícita y sistemática, acceso al currículo e indicadores de progreso. Confirma los procedimientos escolares locales; un diagnóstico clínico no determina por sí solo medidas universales.')],
  ['diagnosticos-concomitantes-relatorio',
    M('Mais de um diagnóstico no relatório: como organizar a informação?', 'More than one diagnosis in a report: how do you organise the information?', 'Más de un diagnóstico en el informe: ¿cómo organizar la información?'),
    M('Condições concomitantes não são uma soma de rótulos: o plano deve partir da interação entre necessidades.', 'Coexisting conditions are not a pile of labels: planning should start with how needs interact.', 'Las condiciones coexistentes no son una suma de etiquetas: el plan parte de cómo interactúan las necesidades.'),
    M('Autismo, TDAH, dificuldades de linguagem, ansiedade, epilepsia, alterações do sono ou outras condições podem coexistir. Cada diagnóstico responde a critérios próprios, mas a criança vive um perfil integrado.', 'Autism, ADHD, language difficulties, anxiety, epilepsy, sleep problems and other conditions may coexist. Each diagnosis has its own criteria, but the child lives one integrated profile.', 'Autismo, TDAH, dificultades de lenguaje, ansiedad, epilepsia, problemas de sueño y otras condiciones pueden coexistir. Cada diagnóstico tiene criterios propios, pero el niño vive un perfil integrado.'),
    M('Uma necessidade pode ampliar outra: linguagem pode afetar questionários de comportamento; sono pode afetar atenção; ansiedade pode mudar participação. A equipa deve evitar atribuir tudo ao primeiro diagnóstico.', 'One need may amplify another: language can affect behaviour questionnaires; sleep can affect attention; anxiety can change participation. Teams should avoid attributing everything to the first diagnosis.', 'Una necesidad puede amplificar otra: el lenguaje afecta cuestionarios de conducta; el sueño, la atención; la ansiedad, la participación. El equipo debe evitar atribuirlo todo al primer diagnóstico.'),
    M('Faça uma tabela por necessidade funcional, não por rótulo: barreira, contexto, apoio, responsável e revisão. Confirme interações entre tratamentos e escolha prioridades partilhadas entre profissionais e família.', 'Make a table by functional need rather than label: barrier, setting, support, responsible person and review. Check treatment interactions and agree shared priorities across professionals and family.', 'Haz una tabla por necesidad funcional, no por etiqueta: barrera, contexto, apoyo, responsable y revisión. Comprueba interacciones entre tratamientos y acuerda prioridades compartidas.')],
  ['prognostico-relatorio-o-que-esperar',
    M('Prognóstico no relatório: o que é possível esperar?', 'Prognosis in a report: what can you expect?', 'Pronóstico en el informe: ¿qué se puede esperar?'),
    M('Falar do futuro com honestidade, esperança e espaço para incerteza.', 'Talking about the future with honesty, hope and room for uncertainty.', 'Hablar del futuro con honestidad, esperanza y espacio para la incertidumbre.'),
    M('Prognóstico é uma estimativa baseada no conhecimento disponível sobre grupos e no perfil individual; não é uma sentença. O desenvolvimento depende de múltiplos fatores e trajetórias individuais variam.', 'A prognosis is an estimate based on group knowledge and the individual profile; it is not a sentence. Development depends on many factors and individual pathways vary.', 'El pronóstico es una estimación basada en conocimientos de grupo y perfil individual; no es una sentencia. El desarrollo depende de muchos factores y las trayectorias varían.'),
    M('Frases absolutas sobre aquilo que a criança “nunca” fará exigem especial cautela, tal como promessas de recuperação garantida. Uma postura positiva reconhece dificuldades e possibilidades sem inventar certezas.', 'Absolute claims about what a child will “never” do require caution, as do promises of guaranteed recovery. A positive stance acknowledges both difficulties and possibilities without inventing certainty.', 'Las afirmaciones absolutas sobre lo que el niño «nunca» hará exigen cautela, igual que las promesas de recuperación garantizada. Una postura positiva reconoce dificultades y posibilidades sin inventar certezas.'),
    M('Pergunte o que se sabe com maior confiança, o que permanece incerto, que fatores podem ser apoiados e qual o horizonte da estimativa. Planeie o próximo passo concreto em vez de tentar resolver toda a vida numa consulta.', 'Ask what is known with more confidence, what remains uncertain, which factors can be supported and the time horizon of the estimate. Plan the next concrete step rather than solving a lifetime in one appointment.', 'Pregunta qué se sabe con más confianza, qué sigue incierto, qué factores pueden apoyarse y cuál es el horizonte. Planifica el siguiente paso concreto en vez de resolver toda una vida en una consulta.')],
  ['explicar-diagnostico-crianca',
    M('Como falar com a criança sobre o diagnóstico?', 'How do you talk to a child about a diagnosis?', '¿Cómo hablar con el niño sobre el diagnóstico?'),
    M('Uma conversa adequada à idade, centrada em identidade, pontos fortes, necessidades e apoio.', 'An age-appropriate conversation centred on identity, strengths, needs and support.', 'Una conversación adaptada a la edad, centrada en identidad, fortalezas, necesidades y apoyo.'),
    M('A criança pode já notar diferenças, dificuldades ou consultas. Informação honesta e adequada ao desenvolvimento pode reduzir culpa e confusão; o momento e a forma devem considerar comunicação, maturidade e vontade de saber.', 'A child may already notice differences, difficulties or appointments. Honest, developmentally appropriate information can reduce blame and confusion; timing and format should consider communication, maturity and desire to know.', 'El niño puede notar diferencias, dificultades o consultas. La información honesta y adaptada puede reducir culpa y confusión; el momento y la forma deben considerar comunicación, madurez y deseo de saber.'),
    M('Apresente o diagnóstico como uma parte da pessoa e uma linguagem para compreender necessidades, não como defeito ou identidade total. Inclua capacidades, interesses, desafios, direitos à dignidade e formas de pedir ajuda.', 'Present diagnosis as one part of a person and a language for understanding needs, not a defect or total identity. Include abilities, interests, challenges, dignity and ways to ask for help.', 'Presenta el diagnóstico como una parte de la persona y un lenguaje para comprender necesidades, no como defecto ni identidad total. Incluye capacidades, intereses, retos, dignidad y formas de pedir ayuda.'),
    M('Combine com o profissional palavras simples, escolha um momento calmo e deixe espaço para perguntas posteriores. Proteja a privacidade: envolva a criança, conforme possível, nas decisões sobre quem recebe a informação.', 'Agree simple wording with the professional, choose a calm moment and leave room for later questions. Protect privacy: involve the child, as far as possible, in deciding who receives the information.', 'Acuerda palabras sencillas con el profesional, elige un momento tranquilo y deja espacio para preguntas posteriores. Protege la privacidad: implica al niño, cuando sea posible, en decidir quién recibe la información.')],
  ['plano-familiar-depois-relatorio',
    M('Depois do relatório: um plano familiar para os próximos 30 dias', 'After the report: a family plan for the next 30 days', 'Después del informe: un plan familiar para los próximos 30 días'),
    M('Passos pequenos e coordenados para sair da dúvida sem tentar fazer tudo de uma vez.', 'Small coordinated steps to move forward without trying to do everything at once.', 'Pasos pequeños y coordinados para avanzar sin intentar hacerlo todo a la vez.'),
    M('Nos primeiros dias, dê tempo para ler e reagir. Separe factos, emoções e tarefas; não é necessário tomar todas as decisões imediatamente, salvo orientações urgentes de saúde ou segurança.', 'In the first days, allow time to read and react. Separate facts, feelings and tasks; not every decision is needed immediately, except urgent health or safety advice.', 'En los primeros días, da tiempo para leer y reaccionar. Separa hechos, emociones y tareas; no hay que tomar todas las decisiones de inmediato, salvo indicaciones urgentes de salud o seguridad.'),
    M('Escolha até três prioridades: esclarecer uma dúvida, contactar um serviço e testar uma adaptação simples numa rotina. Guarde documentos, datas e contactos num único local e defina quem acompanha cada passo.', 'Choose up to three priorities: clarify one question, contact one service and try one simple adjustment in a routine. Keep documents, dates and contacts together and decide who follows each step.', 'Elige hasta tres prioridades: aclarar una duda, contactar un servicio y probar una adaptación sencilla en una rutina. Guarda documentos, fechas y contactos juntos y decide quién sigue cada paso.'),
    M('No fim do mês, reveja: o que ajudou, o que foi inviável, que dúvida continua e qual o próximo passo. Preserve também rotinas agradáveis e tempo de família; a criança continua a ser muito mais do que o relatório.', 'At month end, review what helped, what was not feasible, what remains unclear and the next step. Preserve enjoyable routines and family time too; the child remains far more than the report.', 'Al final del mes, revisa qué ayudó, qué no fue viable, qué duda sigue y cuál es el siguiente paso. Conserva rutinas agradables y tiempo familiar; el niño sigue siendo mucho más que el informe.')],
]

const langText = {
  pt: { kind:'Relatórios sem dúvidas', intro:title => `<strong>${title}</strong> é uma dúvida frequente depois de uma avaliação. Um relatório deve ajudar a compreender a criança e a decidir apoios; não deve ser lido como uma sentença nem como uma descrição completa da pessoa.`, know:'O que esta parte do relatório quer dizer?', limits:'O que não se deve concluir?', act:'Que passos pode a família dar agora?', sum:'Ideias principais', conclusion:'Conclusão', faq:'Perguntas frequentes', q:'Que perguntas devo levar à consulta?', answer:'Peça exemplos do quotidiano, limites da interpretação, prioridades, responsáveis e data de revisão. Se uma frase continuar pouco clara, solicite explicação em linguagem acessível.', notice:'Este artigo é informativo e não substitui avaliação, esclarecimento do profissional que elaborou o relatório nem aconselhamento individual.' },
  en: { kind:'Reports made clearer', intro:title => `<strong>${title}</strong> is a common question after assessment. A report should help people understand a child and plan support; it is not a sentence or a complete description of the person.`, know:'What does this part of the report mean?', limits:'What should you not conclude?', act:'What can the family do now?', sum:'Key ideas', conclusion:'Conclusion', faq:'Frequently asked questions', q:'What questions should I take to the appointment?', answer:'Ask for everyday examples, interpretation limits, priorities, responsible people and a review date. If wording remains unclear, request an accessible explanation.', notice:'This article is for information and does not replace assessment, clarification from the report author or individual advice.' },
  es: { kind:'Informes sin dudas', intro:title => `<strong>${title}</strong> es una duda frecuente después de una evaluación. Un informe debe ayudar a comprender al niño y planificar apoyos; no es una sentencia ni una descripción completa de la persona.`, know:'¿Qué quiere decir esta parte del informe?', limits:'¿Qué no debe concluirse?', act:'¿Qué pasos puede dar ahora la familia?', sum:'Ideas principales', conclusion:'Conclusión', faq:'Preguntas frecuentes', q:'¿Qué preguntas debo llevar a la consulta?', answer:'Pide ejemplos cotidianos, límites de interpretación, prioridades, responsables y fecha de revisión. Si una frase sigue sin estar clara, solicita una explicación accesible.', notice:'Este artículo es informativo y no sustituye la evaluación, la aclaración del profesional que elaboró el informe ni el asesoramiento individual.' },
}
const slugify = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
const titleTag = (title, lang) => {
  const brand = lang === 'pt' ? 'Fala+' : lang === 'en' ? 'Talk+' : 'Habla+'
  const limit = 60 - brand.length - 3
  const short = title.length <= limit ? title : title.slice(0, limit + 1).replace(/\s+\S*$/, '')
  return `${short} · ${brand}`
}

export const REPORT_GUIDE_ARTICLES = T.map(([id, title, teaser, meaning, limits, action]) => ({ id, title, teaser, meaning, limits, action }))
export const REPORT_GUIDE_CATALOG = REPORT_GUIDE_ARTICLES.map(a => ({ id:a.id, theme:'avaliacao', kind:M(langText.pt.kind, langText.en.kind, langText.es.kind), ...Object.fromEntries(['pt','en','es'].map(lang => [lang, { live, slug:a.id === 'primeira-leitura-relatorio-clinico' ? M('recebi-relatorio-crianca-por-onde-comecar','received-child-report-where-start','recibi-informe-por-donde-empezar')[lang] : slugify(a.title[lang]), title:a.title[lang], teaser:a.teaser[lang] }])) }))

export function getReportGuideArticle(id, lang) {
  const a = REPORT_GUIDE_ARTICLES.find(item => item.id === id)
  if (!a) throw new Error(`Unknown report guide article: ${id}`)
  const ui = langText[lang]
  const blocks = [
    { h2:ui.know, id:'o-que-significa', toc:ui.know }, { p:a.meaning[lang] },
    { h2:ui.limits, id:'limites', toc:ui.limits }, { p:a.limits[lang] },
    { h2:ui.act, id:'passos-seguintes', toc:ui.act }, { p:a.action[lang] },
    { summary:[a.meaning[lang], a.action[lang]] },
    { h2:ui.conclusion, id:'conclusao', toc:ui.conclusion }, { p:`${a.action[lang]} ${ui.notice}` },
  ]
  return {
    id, slug:REPORT_GUIDE_CATALOG.find(x => x.id === id)[lang].slug, theme:'avaliacao', short:a.title[lang], date:'2026-10-29',
    titleTag:titleTag(a.title[lang], lang), description:a.teaser[lang],
    keywords:[a.title[lang].toLowerCase(), lang === 'pt' ? 'como entender laudo infantil' : lang === 'en' ? 'understanding child assessment report' : 'cómo entender informe infantil', lang === 'pt' ? 'relatório de especialista criança' : lang === 'en' ? 'child specialist report' : 'informe de especialista infantil'],
    h1:`<span class="word-highlight">${a.title[lang]}</span>`, lead:ui.intro(a.title[lang]), blocks, faqTitle:ui.faq,
    faq:[[ui.know, a.meaning[lang]],[ui.limits, a.limits[lang]],[ui.act, a.action[lang]],[ui.q, ui.answer]],
    sources:id.includes('pontuacao') || id.includes('percentil') || id.includes('confianca') || id.includes('idade-equivalente') ? [L.ashaTools,L.pearson] : id.includes('tdah') ? [L.niceAdhd,L.whoIcf] : id.includes('autismo') ? [L.niceAutism,L.whoIcf] : id.includes('escolar') || id.includes('dislexia') ? [L.ashaSchools,L.ashaTools,L.whoIcf] : S,
    related:['como-compreender-relatorio-clinico-perguntas','relatorios-avaliacao-divergentes-segunda-opiniao','quando-atualizar-avaliacao-desenvolvimento'],
  }
}
